/**
 * 在一致快照上解析依赖闭包：区间可行且每个版本均通过见证闸门。
 * 闭包存在未见证版本时，返回带稳定原因（名称升序列出全部差距）的 422。
 */
private Map<String, ArtifactVersion> resolveClosure(RepositorySnapshot snapshot,
                                                    String rootName, int rootVersion) {
    Map<String, Integer> solution = LockResolver.resolve(
            snapshot, rootName, rootVersion, AttestationGate::isLockEligible);
    if (solution != null) {
        return materialize(snapshot, solution);
    }

    // 失败原因诊断：先在“仅排除撤回”的口径下判断区间是否可行，
    // 以区分“依赖组合不存在”与“闭包内版本未见证/摘要不一致”。
    Map<String, Integer> rangeOnly;
    try {
        rangeOnly = LockResolver.resolve(snapshot, rootName, rootVersion);
    } catch (IllegalArgumentException e) {
        throw ApiException.unprocessable(
                "不存在满足全部依赖区间的未撤回版本组合，无法锁定: " + e.getMessage());
    }
    if (rangeOnly == null) {
        throw ApiException.unprocessable("不存在满足全部依赖区间的未撤回版本组合，无法锁定");
    }

    Map<String, ArtifactVersion> candidates = materialize(snapshot, rangeOnly);
    List<String> reasons = new ArrayList<>();
    for (ArtifactVersion artifact : candidates.values()) {
        reasons.addAll(AttestationGate.violationReasons(artifact));
    }
    if (reasons.isEmpty()) {
        // 理论上不可达：见证口径失败必然存在闸门原因。
        throw ApiException.unprocessable("不存在满足全部依赖区间且见证完整的版本组合，无法锁定");
    }
    throw ApiException.unprocessable("依赖闭包存在未满足见证要求的版本，整次锁定失败: "
            + String.join("; ", reasons));
}

